<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title><?= esc($title) ?> — Academic MCQ Bank</title>
<style>
:root{--navy:#183b56;--blue:#2f6f8f;--teal:#4b9b98;--ink:#203244;--muted:#667b8e;--line:#d9e4eb;--glass:rgba(255,255,255,.78);--shadow:0 18px 48px rgba(24,59,86,.12)}
*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 18px 48px;font-family:Inter,"Segoe UI",Arial,sans-serif;color:var(--ink);background:radial-gradient(ellipse at 8% 5%,#d8eaf0 0,transparent 35%),radial-gradient(ellipse at 92% 10%,#dcebe5 0,transparent 32%),linear-gradient(135deg,#f4f8fb,#edf3f6 58%,#f7f9fb)}
main{max-width:1120px;margin:auto}.hero{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.9);border-radius:24px;padding:28px 30px;margin-bottom:20px;background:linear-gradient(120deg,rgba(255,255,255,.84),rgba(240,248,249,.68));backdrop-filter:blur(18px);box-shadow:var(--shadow)}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:800;color:var(--teal)}h1{margin:8px 0 7px;font-size:clamp(25px,4vw,34px);color:var(--navy);letter-spacing:-.03em}.sub{color:var(--muted);max-width:760px;line-height:1.55}.hero-mark{position:absolute;right:26px;top:25px;width:66px;height:66px;border-radius:20px;display:grid;place-items:center;background:rgba(255,255,255,.64);border:1px solid #fff;color:var(--blue);font-size:29px;box-shadow:0 8px 24px rgba(24,59,86,.08)}
.panel{margin-bottom:18px;padding:24px;border:1px solid rgba(255,255,255,.94);border-radius:20px;background:var(--glass);backdrop-filter:blur(18px);box-shadow:0 10px 30px rgba(24,59,86,.07)}.section-head{display:flex;align-items:center;gap:12px;margin-bottom:17px;padding-bottom:14px;border-bottom:1px solid #e4edf1}.step{width:34px;height:34px;display:grid;place-items:center;flex:none;border-radius:12px;background:#e4f0f2;color:var(--blue);font-weight:800}.section-head h2{margin:0;font-size:17px;color:var(--navy)}.section-head p{margin:3px 0 0;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 20px}.field{min-width:0}.wide{grid-column:1/-1}label{display:block;margin:0 0 7px;font-size:13px;font-weight:750;color:#2d4658}label .req{color:#b75a55}.help{font-size:12px;color:var(--muted);margin-top:6px;line-height:1.4}input,select,textarea{display:block;width:100%;min-width:0;border:1px solid #cbdbe4;border-radius:12px;background:rgba(255,255,255,.88);padding:12px 13px;color:var(--ink);font:inherit;font-size:14px;outline:none;transition:border-color .18s,box-shadow .18s,background .18s}input:focus,select:focus,textarea:focus{border-color:#70aab8;box-shadow:0 0 0 4px rgba(75,155,152,.13);background:#fff}input:disabled,select:disabled{background:#eef3f6;color:#62798b}textarea{min-height:130px;resize:vertical;line-height:1.55}.stemarea{min-height:150px}.option-row{display:grid;grid-template-columns:42px minmax(0,1fr);align-items:center;gap:10px}.option-letter{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:#e8f0f4;color:var(--navy);font-weight:800;border:1px solid #d5e3e9}.choice-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.choice{position:relative}.choice input{position:absolute;opacity:0;pointer-events:none}.choice label{margin:0;padding:12px;text-align:center;border:1px solid #d0dfe6;border-radius:12px;background:rgba(255,255,255,.72);cursor:pointer}.choice input:checked+label{border-color:#4b9b98;background:#e3f2ef;color:#205e5c;box-shadow:inset 0 0 0 1px #4b9b98}.difficulty-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.date-wrap{display:flex;align-items:center;gap:10px}.date-wrap input{background:#edf3f6;color:#526a7c}.lock{font-size:12px;color:#647b8c;white-space:nowrap}.flash{border-radius:14px;padding:14px 17px;margin:0 0 18px}.error{background:rgba(255,239,238,.92);border:1px solid #f0cecb;color:#8d3835}.success{background:#e8f5ef;border:1px solid #c9e5d7;color:#27664b}.flash ul{margin:8px 0 0;padding-left:20px}.buttons{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:22px}.button-group{display:flex;gap:10px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:11px 17px;border:1px solid rgba(255,255,255,.8);border-radius:13px;text-decoration:none;font-weight:750;font-size:13px;cursor:pointer;transition:transform .15s,box-shadow .15s,filter .15s}.btn:hover{transform:translateY(-1px);filter:brightness(1.02)}.btn-glass{color:var(--navy);background:rgba(255,255,255,.66);backdrop-filter:blur(12px);box-shadow:0 7px 18px rgba(24,59,86,.08);border-color:#d5e3e9}.btn-primary{color:white;background:linear-gradient(135deg,#2e6f8f,#397f8e);box-shadow:0 8px 20px rgba(47,111,143,.23)}.btn-submit{color:white;background:linear-gradient(135deg,#2c756c,#4a9a8a);box-shadow:0 8px 20px rgba(44,117,108,.2)}.tiny-note{color:var(--muted);font-size:12px;line-height:1.45}.divider{height:1px;background:#e2ebef;margin:20px 0}@media(max-width:700px){body{padding:14px 10px 30px}.hero{padding:22px}.hero-mark{display:none}.panel{padding:18px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.choice-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.buttons{align-items:stretch}.button-group{width:100%}.btn{flex:1}.date-wrap{align-items:flex-start;flex-direction:column}}
</style></head><body><main>
<header class="hero"><div class="eyebrow">Academic Question Submission</div><h1><?= esc($title) ?></h1><div class="sub">Prepare a clear, curriculum-aligned MCQ for academic review. Save a draft to continue later, or submit the completed question to the administrator.</div><div class="hero-mark" aria-hidden="true">✦</div></header>
<?php $errors = session()->getFlashdata('errors') ?? []; if ($errors): ?><div class="flash error"><strong>Please review these items</strong><ul><?php foreach ($errors as $message): ?><li><?= esc($message) ?></li><?php endforeach ?></ul></div><?php endif ?>
<form method="post" action="<?= esc($action) ?>" autocomplete="off">
<?= csrf_field() ?>
<section class="panel"><div class="section-head"><div class="step">01</div><div><h2>Curriculum Classification</h2><p>Choose the correct academic hierarchy for this question.</p></div></div>
<div class="grid">
<div class="field"><label for="subjectPicker">Subject <span class="req">*</span></label><select id="subjectPicker" disabled><?php foreach ($subjects as $subject): ?><option value="<?= esc($subject['subject_id']) ?>" <?= (string)$selectedSubjectId === (string)$subject['subject_id'] ? 'selected' : '' ?>><?= esc($subject['subject_name']) ?></option><?php endforeach ?></select><input type="hidden" id="subject_id" name="subject_id" value="<?= esc($selectedSubjectId) ?>"><div class="help">Your Subject is assigned by the administrator and cannot be changed here.</div></div>
<div class="field"><label for="subdiscipline_id">Sub Discipline <span class="req" id="disciplineRequired"></span></label><select id="subdiscipline_id" name="subdiscipline_id"><option value="">Select Sub Discipline</option></select><div class="help" id="disciplineHint">Loading available Sub Disciplines…</div></div>
<div class="field"><label for="system_id">System <span class="req">*</span></label><select id="system_id" name="system_id" required disabled><option value="">Select System</option></select></div>
<div class="field"><label for="topic_id">Topic <span class="req">*</span></label><select id="topic_id" name="topic_id" required disabled><option value="">Select Topic</option></select></div>
<div class="field"><label for="progId">Program <span class="req">*</span></label><select id="progId" name="progId" required><option value="">Select Program</option><?php foreach ($programs as $program): ?><option value="<?= esc($program['progId']) ?>" <?= (string)old('progId','') === (string)$program['progId'] ? 'selected' : '' ?>><?= esc($program['progName']) ?></option><?php endforeach ?></select></div>
<div class="field"><label for="submission_date">Submission Date</label><div class="date-wrap"><input id="submission_date" type="text" value="<?= esc($today) ?>" disabled><span class="lock">▣ Automatically recorded</span></div><div class="help">The server records the actual submission time; this display is not editable.</div></div>
</div></section>
<section class="panel"><div class="section-head"><div class="step">02</div><div><h2>Question Content</h2><p>Keep the clinical/scenario stem separate from the question lead-in.</p></div></div>
<div class="grid"><div class="field wide"><label for="stem">Stem <span class="req">*</span></label><textarea class="stemarea" id="stem" name="stem" placeholder="Enter the clinical scenario, case, or question context…"><?= esc(old('stem','')) ?></textarea><div class="help">Required before submission. You may save an incomplete draft.</div></div>
<div class="field wide"><label for="leadin">Lead-in <span class="req">*</span></label><textarea id="leadin" name="leadin" placeholder="For example: Which of the following is the most likely diagnosis?…"><?= esc(old('leadin','')) ?></textarea><div class="help">Ask one precise question that can be answered from the stem and options.</div></div></div></section>
<section class="panel"><div class="section-head"><div class="step">03</div><div><h2>Answer Options</h2><p>Provide five plausible options and select one correct answer.</p></div></div>
<div class="grid"><?php foreach (['A','B','C','D','E'] as $idx => $letter): $n=$idx+1; ?><div class="field"><label for="option<?= $n ?>">Option <?= $letter ?> <span class="req">*</span></label><div class="option-row"><div class="option-letter"><?= $letter ?></div><input id="option<?= $n ?>" name="option<?= $n ?>" maxlength="255" value="<?= esc(old('option'.$n,'')) ?>" placeholder="Enter option <?= $letter ?>"></div></div><?php endforeach ?>
<div class="field"><label for="mkey">Correct Answer <span class="req">*</span></label><select id="mkey" name="mkey"><option value="">Select correct option</option><?php foreach (['A','B','C','D','E'] as $letter): ?><option value="<?= $letter ?>" <?= old('mkey')===$letter?'selected':'' ?>>Option <?= $letter ?></option><?php endforeach ?></select></div></div></section>
<section class="panel"><div class="section-head"><div class="step">04</div><div><h2>Academic Metadata</h2><p>Choose the competency and difficulty level for the item.</p></div></div>
<div class="grid"><div class="field"><label>Competency <span class="req">*</span></label><div class="choice-grid"><?php for($c=1;$c<=4;$c++): ?><div class="choice"><input type="radio" id="competency<?= $c ?>" name="competency" value="<?= $c ?>" <?= (string)old('competency','')===(string)$c?'checked':'' ?>><label for="competency<?= $c ?>"><?= $c ?></label></div><?php endfor ?></div></div>
<div class="field"><label>Difficulty Level <span class="req">*</span></label><div class="choice-grid difficulty-grid"><?php foreach(['Difficult','Moderate','Easy'] as $level): ?><div class="choice"><input type="radio" id="difficulty<?= $level ?>" name="difficulty" value="<?= $level ?>" <?= old('difficulty','Moderate')===$level?'checked':'' ?>><label for="difficulty<?= $level ?>"><?= $level ?></label></div><?php endforeach ?></div></div>
<div class="field"><label for="learning_objective">Learning Objective <span class="tiny-note">(Optional)</span></label><input id="learning_objective" name="learning_objective" maxlength="500" value="<?= esc(old('learning_objective','')) ?>" placeholder="Learning objective"></div>
<div class="field"><label for="book_title">Book Title <span class="tiny-note">(Optional)</span></label><input id="book_title" name="book_title" maxlength="255" value="<?= esc(old('book_title','')) ?>" placeholder="Reference book title"></div>
<div class="field"><label for="name_of_bookauthor">Book Author <span class="tiny-note">(Optional)</span></label><input id="name_of_bookauthor" name="name_of_bookauthor" maxlength="255" value="<?= esc(old('name_of_bookauthor','')) ?>" placeholder="Author name"></div>
<div class="field"><label for="edition">Edition <span class="tiny-note">(Optional)</span></label><input id="edition" name="edition" maxlength="100" value="<?= esc(old('edition','')) ?>" placeholder="Edition"></div>
<div class="field"><label for="page_no">Page Number <span class="tiny-note">(Optional)</span></label><input id="page_no" name="page_no" maxlength="10" value="<?= esc(old('page_no','')) ?>" placeholder="Page"></div></div>
<div class="divider"></div><div class="tiny-note">Your draft remains private to your account. Submitting sends the completed question to the administrator's review queue and removes it from your draft list.</div>
<div class="buttons"><a class="btn btn-glass" href="<?= site_url('master/mcqs/my-questions') ?>">← My Questions</a><div class="button-group"><button class="btn btn-primary" type="submit" name="intent" value="draft">▣ Save Draft</button><button class="btn btn-submit" type="submit" name="intent" value="submit" onclick="return confirm('Submit this question to the administrator for review?');">✓ Submit Question</button></div></div></section>
</form></main>
<script>
(() => {
 const subject = document.getElementById('subject_id');
 const discipline = document.getElementById('subdiscipline_id');
 const system = document.getElementById('system_id');
 const topic = document.getElementById('topic_id');
 const hint = document.getElementById('disciplineHint');
 const requiredMark = document.getElementById('disciplineRequired');
 const initial = { discipline: <?= json_encode((string)old('subdiscipline_id','')) ?>, system: <?= json_encode((string)old('system_id','')) ?>, topic: <?= json_encode((string)old('topic_id','')) ?> };
 const disciplineUrl = <?= json_encode(site_url('master/subdisciplines-by-subject')) ?>;
 const systemsUrl = <?= json_encode(site_url('master/mcqs/systems-by-subject')) ?>;
 const topicsUrl = <?= json_encode(site_url('master/mcqs/topics-by-system')) ?>;
 function reset(sel,label){sel.innerHTML='';const o=document.createElement('option');o.value='';o.textContent=label;sel.appendChild(o);sel.disabled=true;}
 async function loadDisciplines(keep=false){reset(discipline,'Loading Sub Disciplines…');reset(system,'Select System');reset(topic,'Select Topic');hint.textContent='Loading available Sub Disciplines…';
 if(!subject.value){reset(discipline,'Select Sub Discipline');hint.textContent='No Subject is assigned to this account.';return;}
 try{const r=await fetch(disciplineUrl+'/'+encodeURIComponent(subject.value),{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();const items=d.subdisciplines||[];reset(discipline,'Select Sub Discipline');items.forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;discipline.appendChild(o)});
 if(items.length){discipline.disabled=false;discipline.required=true;requiredMark.textContent='*';hint.textContent='Select a Sub Discipline before choosing a System.';if(keep&&initial.discipline)discipline.value=initial.discipline;if(discipline.value)await loadSystems(keep);else hint.textContent='Sub Discipline is required for this Subject.';}
 else{discipline.disabled=true;discipline.required=false;requiredMark.textContent='';hint.textContent='No Sub Disciplines apply to this Subject; continue with System.';await loadSystems(false);}
 }catch(e){reset(discipline,'Unable to load Sub Disciplines');hint.textContent='Could not load Sub Disciplines. Refresh and try again.';console.error(e)}}
 async function loadSystems(keep=false){reset(system,'Loading Systems…');reset(topic,'Select Topic');if(!subject.value){reset(system,'Select System');return;}const p=new URLSearchParams();if(discipline.value)p.set('subdiscipline_id',discipline.value);
 try{const r=await fetch(systemsUrl+'/'+encodeURIComponent(subject.value)+'?'+p.toString(),{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();reset(system,'Select System');(d.systems||[]).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;system.appendChild(o)});system.disabled=false;if(keep&&initial.system){system.value=initial.system;if(system.value)await loadTopics(true)}}catch(e){reset(system,'Unable to load Systems');console.error(e)}}
 async function loadTopics(keep=false){reset(topic,'Loading Topics…');if(!system.value){reset(topic,'Select Topic');return;}try{const r=await fetch(topicsUrl+'/'+encodeURIComponent(system.value),{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();reset(topic,'Select Topic');(d.topics||[]).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;topic.appendChild(o)});topic.disabled=false;if(keep&&initial.topic)topic.value=initial.topic}catch(e){reset(topic,'Unable to load Topics');console.error(e)}}
 discipline.addEventListener('change',()=>{initial.system='';initial.topic='';loadSystems(false)});system.addEventListener('change',()=>{initial.topic='';loadTopics(false)});loadDisciplines(true);
})();
</script></body></html>
